const configItems = $input.all();
const agg = $('Aggregate Snapshots').first().json;
const snapshots = agg.snapshots || [];
const run_id = agg.run_id;
const snapshotLookup = {};
for (const snap of snapshots) {
  if (snap.source_url) snapshotLookup[snap.source_url] = snap.last_hash || '';
}
const ALLOWED_SOURCE_TYPES = ['website', 'docs', 'blog', 'github', 'changelog', 'release-notes', 'developer'];
const SOURCE_TYPE_MAP = { 'developer': 'docs' };
const urlQueue = [];
for (const item of configItems) {
  const c = item.json;
  const url = (c.url || c.URL || '').trim();
  const rawSourceType = (c.source_type || '').toLowerCase();
  if (!url) continue;
  if (!ALLOWED_SOURCE_TYPES.includes(rawSourceType)) continue;
  const sourceType = SOURCE_TYPE_MAP[rawSourceType] || rawSourceType;
  urlQueue.push({ competitor_id: c.competitor_id, name: c.name, tier: c.tier || 'unknown', source_type: sourceType, url: url, previous_hash: snapshotLookup[url] || '' });
}
return [{ json: { url_queue: urlQueue, run_id, total_urls: urlQueue.length } }];

function hashString(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}
const d = $input.item.json;
const content = d.data || '';
const previousHash = d.previous_hash || '';
const newHash = hashString(content.substring(0, 100000) || 'empty');
const changed = newHash !== previousHash && content.length > 200;
return { json: { competitor_id: d.competitor_id, name: d.name, tier: d.tier, source_type: d.source_type, url: d.url, previous_hash: previousHash, jina_url: 'https://r.jina.ai/' + d.url, new_hash: newHash, changed, content_length: content.length, content_preview: content.substring(0, 8000), checked_at: new Date().toISOString() } };

// Build Anthropic prompt — runs once per item
const item = $input.item.json;

// Strip tracking pixel lines and clean content
const rawPreview = item.content_preview || '';
const cleanLines = rawPreview.split('
').filter(line => {
  const s = line.trim();
  if (!s) return false;
  if (/^\[Image \d+\]\(https?:///.test(s)) return false;
  if (/^https?://[^\s]+[?&](adroll|pv=|arrfrr|fpc=|_hsenc|utm_)/.test(s)) return false;
