});
const cleanContent = cleanLines.join('
').trim();
const cleanLength = cleanContent.length;

if (cleanLength < 300) {
  return { json: { ...item, skip: true, skip_reason: `content_too_short:${cleanLength}` } };
}

const systemPrompt = `You are a product intelligence analyst specializing in IAM (Identity and Access Management). Extract concrete, evidence-based signals from competitor content.

LANE DEFINITIONS:
- IDENTITY_EXPERIENCE: login widgets, hosted pages, branding, end-user journeys, authentication UX. Keywords: login widget, hosted login, branded, end-user, account portal, sign-in page, magic link, passkey UX
- DEVELOPER_PLATFORM: SDKs, developer docs, sample apps, quickstarts, API reference, developer portal, DX. Keywords: SDK, developer docs, quickstart, API reference, npm, sample app, CLI
- AI_AGENT_IDENTITY: agent authorization, MCP, A2A, non-human identity, LLM-powered identity. Keywords: MCP, agent, A2A, LLM, machine identity, non-human, AI assistant
- UI_ARCHITECTURE: design systems, composable UI, headless patterns, theming, accessibility. Keywords: design system, headless, composable, component library, theming, WCAG
- DESIGN_WORKFLOWS: Figma integrations, design-to-code, mockup tools, design tokens. Keywords: Figma, design token, prototype, mockup, no-code, low-code designer
- STRATEGIC_SIGNALS: pricing, launches, acquisitions, partnerships, hiring, funding. Keywords: pricing, launch, GA, acquired, partnership, hired, funding, enterprise

EVIDENCE RULES:
- No marketing language inference (seamless, intelligent, AI-powered = not evidence)
- No code-existence inference (GitHub code is NOT evidence of a shipped feature)
- Confidence 4-5: changelog or GA announcement. Confidence 2-3: blog or docs. Confidence 1: marketing only - set not_enough_evidence true
- Set not_enough_evidence: true if content is generic, vague, or purely marketing language

Output ONLY valid JSON, no markdown, no code blocks.`;

const userPrompt = `Competitor: ${item.name} (${item.competitor_id})
Source: ${item.source_type} - ${item.url}
Content:
${cleanContent}

Output ONLY valid JSON:
{"summary":"","observed_fact":"","analyst_interpretation":"","product_area":"","lane":"DEVELOPER_PLATFORM","importance_score":3,"confidence_score":3,"evidence_strength":"direct","not_enough_evidence":false}`;

return { json: { ...item, skip: false, systemPrompt, userPrompt, clean_length: cleanLength } };

// Get original item data from prompt builder (paired item)
const origItem = $('Build Haiku Prompt').item.json;

// Get API response for this item
const apiResponse = $input.item.json;

let ai = {};
try {
  const text = apiResponse.content?.[0]?.text || '';
  const match = text.match(/\{[\s\S]*\}/);
  if (match) ai = JSON.parse(match[0]);
} catch(e) { ai = { not_enough_evidence: true }; }

// Drop records with not_enough_evidence or confidence <= 1
if (ai.not_enough_evidence) return { json: { _dropped: true } };
if ((ai.confidence_score || 0) <= 1) return { json: { _dropped: true } };

const now = new Date().toISOString();
return { json: {
  ev_id: `EV-${Date.now()}-${Math.random().toString(36).substr(2,5)}`,
  date_found: now,
  week: now.substring(0,7),
  competitor_id: origItem.competitor_id,
  source_type: origItem.source_type,
  source_url: origItem.url,
  title: `${origItem.name} ${origItem.source_type} update`,
  summary: ai.summary || '',
  observed_fact: ai.observed_fact || '',
  analyst_interpretation: ai.analyst_interpretation || '',
  product_area: ai.product_area || '',
  lane: (ai.lane || '').toUpperCase(),
  importance_score: ai.importance_score || 2,
  confidence_score: ai.confidence_score || 2,
  freshness: 'this_week',
  evidence_strength: ai.evidence_strength || 'inferred',
  status: 'new',
  new_hash: origItem.new_hash,
  snapshot_url: origItem.url,
  checked_at: origItem.checked_at
} };

const BASE_SCORES = {
  changelog:             3,
  release_notes:         3,
  product_documentation: 3,
  documentation:         3,
  developer_portal:      2,
  github:                1,
  github_repo:           1,
  blog:                  1,
  homepage:              0
};

const PHRASE_KEYWORDS = [
  'login widget', 'platform ui', 'end-user ui', 'hosted pages',
  'hosted account', 'sample app', 'developer portal', 'login experience',
  'release notes'
];

const WORD_KEYWORDS = [
  'mcp', 'sdk', 'flutter', 'astro', 'localization', 'customization',
  'orchestration', 'android', 'ios', 'javascript', 'docs',
  'authentication', 'identity', 'oauth', 'oidc', 'saml', 'mfa',
  'passkey', 'webauthn', 'developer', 'api', 'mobile', 'login', 'auth'
];

const GITHUB_REPO_TERMS = [
  'mcp', 'sdk', 'login-widget', 'login_widget',
  'android', 'ios', 'flutter', 'astro',
  'platform-ui', 'platform_ui', 'end-user-ui', 'end_user_ui'
];

const THRESHOLD = 3;
const BODY_CAP = 5;

function extractTitleAndBody(content) {
  const lines = content.split('\n');
  let titleLineIdx = -1;
  let title = '';

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].startsWith('# ')) {
      titleLineIdx = i;
      title = lines[i].slice(2).trim();
      break;
    }
  }

  if (titleLineIdx === -1) {
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].trim()) {
        titleLineIdx = i;
        title = lines[i].trim();
        break;
      }
    }
  }

  const body = titleLineIdx >= 0
    ? lines.slice(titleLineIdx + 1).join('\n')
    : content;

  return { title, body };
}

function findKeywords(text) {
  const lower = text.toLowerCase();
  const found = new Set();

  for (const phrase of PHRASE_KEYWORDS) {
    if (lower.includes(phrase)) found.add(phrase);
  }
  for (const word of WORD_KEYWORDS) {
    if (lower.includes(word)) found.add(word);
  }
  return found;
}

function extractRepoName(url) {
  const match = url.match(/github\.com\/[^/]+\/([^/?#]+)/i);
  return match ? match[1].toLowerCase() : null;
}

const results = [];

for (const item of $input.all()) {
  const data = item.json;
  const sourceType = String(data.source_type || '').toLowerCase();
  const content = String(data.content_preview || '');
  const url = String(data.url || '');

  const baseScore = Object.prototype.hasOwnProperty.call(BASE_SCORES, sourceType)
    ? BASE_SCORES[sourceType]
    : 1;

  const { title, body } = extractTitleAndBody(content);

  const titleKws = findKeywords(title);
  const bodyKws  = findKeywords(body);

  const titleMatches = titleKws.size;
  const bodyMatches  = Math.min(bodyKws.size, BODY_CAP);

  const allKws = new Set([...titleKws, ...bodyKws]);
  let keywordsMatched = allKws.size;

  // GitHub repo-name bonus (+2, same as title weight)
  let repoBonus = 0;
  if (sourceType === 'github' || sourceType === 'github_repo') {
    const repoName = extractRepoName(url);
    if (repoName) {
      for (const term of GITHUB_REPO_TERMS) {
        if (repoName.includes(term)) {
          repoBonus = 2;
          if (!allKws.has(term)) {
            keywordsMatched++;
            allKws.add(term);
          }
          break;
        }
      }
    }
  }

  const score = baseScore + (titleMatches * 2) + bodyMatches + repoBonus;
  const pass  = score >= THRESHOLD && keywordsMatched >= 1;

  results.push({
    json: {
      ...data,
      relevance_score: score,
      relevance_pass:  pass,
      keywords_matched: keywordsMatched
    }
  });
}

return results;

